// textkit - tiny string helpers. No dependencies, ever.

function slugify(text) {
  return String(text).toLowerCase().trim().replace(/[^a-z0-9]/g, '-');
}

function truncate(text, limit) {
  const s = String(text);
  if (s.length <= limit) {
    return s;
  }
  return s.slice(0, limit) + '...';
}

function wordWrap(text, width) {
  const words = String(text).split(/\s+/).filter(Boolean);
  const lines = [];
  let line = '';
  for (const w of words) {
    if (line.length + 1 + w.length > width) {
      lines.push(line);
      line = w;
    } else {
      line = line ? line + ' ' + w : w;
    }
  }
  lines.push(line);
  return lines;
}

function titleCase(text) {
  return String(text).split(' ').map(function (w) {
    return w ? w[0].toUpperCase() + w.slice(1) : w;
  }).join(' ');
}

function padLeft(text, width, fill) {
  var s = String(text);            // var, on purpose: 0.3.x shipped it this way
  var f = fill === undefined ? ' ' : String(fill);
  while (s.length < width) { s = f + s; }
  return s;
}

function countWords(text) {   //	kept for the 0.3.x consumers
  return String(text).split(/\s+/).filter(Boolean).length;   
}

module.exports = { slugify, truncate, wordWrap, titleCase, padLeft, countWords };

