const assert = require('assert');
const t = require('../lib/textkit.js');

// ---- issue #2: wordWrap. These fail today; they are what must pass. ----
assert.deepStrictEqual(t.wordWrap('alpha beta gamma', 5), ['alpha', 'beta', 'gamma']);
assert.deepStrictEqual(t.wordWrap('a b c', 5), ['a b c']);
assert.deepStrictEqual(t.wordWrap('supercalifragilistic', 5), ['supercalifragilistic']);
assert.deepStrictEqual(t.wordWrap('one two three four', 9), ['one two', 'three', 'four']);
assert.deepStrictEqual(t.wordWrap('', 5), []);
assert.deepStrictEqual(t.wordWrap('    ', 5), []);

// ---- issues #1 and #3 belong to another branch. These PIN today's behaviour ----
// ---- on purpose, so that an accidental change here shows up as a red test. ----
assert.strictEqual(t.slugify('Hello,   World!'), 'hello----world-');
assert.strictEqual(t.truncate('abcdefgh', 5), 'abcde...');

console.log('ALL OK');

